"""Render a sortable, searchable overview of all story measurements; no external assets."""
import html,json,statistics,csv
from pathlib import Path
from voice_bridge.settings import ROOT


def main():
 root=ROOT/'docs/advanced-story';summary=json.loads((root/'summary.json').read_text());rows=[]
 for name in ('story-20261017','story-extended-20261017'):
  data=json.loads((ROOT/'logs/advanced-story'/name/'results.json').read_text())
  for row in data['samples']:rows.append((name,row))
 fields=['case','kind','variant','wer','cer','input_seconds','complete_seconds','stt_queue_decode_seconds','stt_decode_seconds','llm_first_text_seconds','tts_batch_compute_seconds','cpu_peak_pct_machine','cpu_mean_pct_machine','server_rss_peak_mib','gpu_peak_mib','gpu_util_peak_pct','audio_chunks','completed_chunks']
 with (root/'per-sample.csv').open('w',newline='') as output:
  writer=csv.DictWriter(output,fieldnames=fields);writer.writeheader()
  for folder,row in rows:
   stages=row['timings']['stages'];finals=[s for s in stages if s['stage']=='final_stt'];llm=[s['seconds'] for s in stages if s['stage']=='llm_to_first_text'];r=row['resources']
   writer.writerow(dict(case=row['case']['id'],kind=row['case']['kind'],variant=row['case']['variant'],wer=row['stt_metrics']['wer'],cer=row['stt_metrics']['cer'],input_seconds=row['case']['seconds'],complete_seconds=row['timings']['whole_sample_seconds'],stt_queue_decode_seconds=sum(s['seconds'] for s in finals),stt_decode_seconds=sum(s.get('decode_seconds') or 0 for s in finals),llm_first_text_seconds=statistics.mean(llm) if llm else '',tts_batch_compute_seconds=sum(s['seconds'] for s in stages if s['stage']=='tts_inference'),cpu_peak_pct_machine=(r.get('cpu_pct_machine') or {}).get('peak'),cpu_mean_pct_machine=(r.get('cpu_pct_machine') or {}).get('mean'),server_rss_peak_mib=(r.get('ram_tree_rss_mb') or {}).get('peak'),gpu_peak_mib=(r.get('gpu_vram_mb') or {}).get('peak'),gpu_util_peak_pct=(r.get('gpu_util_pct') or {}).get('peak'),audio_chunks=row['audio_chunks'],completed_chunks=row['completed_playback_chunks']))
 esc=html.escape;body=['<h1>Continuous bilingual story audit</h1><p>50 synthetic continuous-story inputs · 38 mixed-language runs · 239/239 generated audio chunks finished playback. Playback completion does not mean recognition or voice routing was correct.</p><p>Physical microphone and speaker behavior were not tested. Initial GPU low-power timing is identified in the detailed reports. Cloud LLM RAM/VRAM are unavailable.</p><nav><a href="FINDINGS.md">Detailed findings</a><a href="per-sample.csv">Per-sample CSV</a><a href="SUMMARY.md">Full comparison report</a><a href="story-20261017/index.html">Base recordings and raw outputs</a><a href="story-extended-20261017/index.html">Bilingual and long-story outputs</a></nav><h2>Confirmed problems</h2><ul><li>STT sometimes translates or repeats speech instead of preserving both languages.</li><li>Pauses and the 30-second turn cap can cancel recorded input before its final transcript.</li><li>Five bilingual replies omitted voice markers, sending both languages through one voice.</li><li>Earlier conversation memory can conceal missing current input and repeat unconfirmed inferences.</li></ul><h2>Mixed-language recognition</h2><p>Weighted WER/CER, normalized for case and punctuation. Candidate decoders use the same PCM16 captured WAVs; the live pipeline also includes canceled speech. The experimental 5-second and standard 30-second Whisper settings are separate. Replay uses a selected failure/control subset.</p><table><thead><tr><th>Configuration</th><th>Mixed N</th><th>Mixed WER</th><th>Mixed CER</th><th>All N</th><th>All WER</th><th>All CER</th></tr></thead><tbody>']
 for name,values in summary['recognition'].items():
  m=values['mixed'];a=values['all'];body.append('<tr><td>'+esc(name)+f'</td><td>{m["n"]}</td><td>{m["wer"]:.1%}</td><td>{m["cer"]:.1%}</td><td>{a["n"]}</td><td>{a["wer"]:.1%}</td><td>{a["cer"]:.1%}</td></tr>')
 body.append('</tbody></table><h3>Controlled comparison: complete captured mixed stories</h3><p>The all-story fresh-final score includes recovering audio the application discarded. On the 32 complete captured mixed inputs, live progressive Qwen is better than fresh finals. A decoder replacement is not established as a fix.</p><table><thead><tr><th>Configuration</th><th>N</th><th>WER</th><th>CER</th></tr></thead><tbody>')
 for name,values in summary.get('complete_mixed_recognition',{}).items():body.append('<tr><td>'+esc(name)+f'</td><td>{values["n"]}</td><td>{values["wer"]:.1%}</td><td>{values["cer"]:.1%}</td></tr>')
 body.append('</tbody></table><h2>Per-story resources and timing</h2><p>Filter by name or condition. Click a column heading to sort. Click a story to open its input, word differences, raw LLM markers, all generated audio, acknowledgments and full measurements. Stage timings can overlap. Final-STT time covers delivered finals; canceled segments are called out in the detailed review.</p><input id="filter" placeholder="Filter: mixed, pause, noise, long_story…" aria-label="Filter story measurements"><div class="scroll"><table id="samples"><thead><tr>')
 headers=['Story','Kind','WER %','CER %','Input s','Complete s','Final STT queue+decode s','Final STT decode s','LLM first text s','TTS batch compute s','CPU peak % machine','Server RAM peak MiB','Whole GPU peak MiB','Audio finished']
 body.extend('<th tabindex="0">'+esc(h)+'</th>' for h in headers);body.append('</tr></thead><tbody>')
 def peak(row,key):return (row['resources'].get(key) or {}).get('peak')
 def display(value):return '—' if value is None else f'{value:.2f}'
 for folder,row in rows:
  c=row['case'];stages=row['timings']['stages'];final=[s for s in stages if s['stage']=='final_stt'];llm=[s['seconds'] for s in stages if s['stage']=='llm_to_first_text'];tts=[s['seconds'] for s in stages if s['stage']=='tts_inference']
  values=[c['kind'],row['stt_metrics']['wer']*100,row['stt_metrics']['cer']*100,c['seconds'],row['timings']['whole_sample_seconds'],sum(s['seconds'] for s in final) if final else None,sum(s['decode_seconds'] or 0 for s in final) if final else None,statistics.mean(llm) if llm else None,sum(tts) if tts else None,peak(row,'cpu_pct_machine'),peak(row,'ram_tree_rss_mb'),peak(row,'gpu_vram_mb')]
  body.append('<tr><td><a href="'+folder+'/index.html#'+esc(c['id'])+'">'+esc(c['id'])+'</a></td>')
  for value in values:body.append('<td>'+ (esc(value) if isinstance(value,str) else display(value))+'</td>')
  body.append(f'<td>{row["completed_playback_chunks"]}/{row["audio_chunks"]}</td></tr>')
 body.append('</tbody></table></div><h2>Recorded findings</h2><ul>')
 for finding,count in sorted(summary['findings'].items(),key=lambda x:-x[1]):body.append('<li>'+str(count)+' runs: '+esc(finding)+'</li>')
 body.append('</ul><p>Findings include transparent lexical/semantic heuristics, not a certified factuality score. Every native generated WAV has an ASR agreement diagnostic; that does not replace human listening. GPU measurements include other device users. System RAM measurements refer to the WSL guest, not the Windows host. RSS sums can count shared pages twice, and sampling can miss short peaks. The same narrative is repeated with persistent test memory, which can conceal lost current input. Test memory is separate from your normal conversation.</p>')
 css='body{margin:30px auto;max-width:1500px;padding:24px;background:#101824;color:#e7effb;font:15px system-ui;line-height:1.5}a{color:#80c9ff}nav{display:flex;gap:18px;flex-wrap:wrap}h2{margin-top:32px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:10px;border-bottom:1px solid #34465f;text-align:left}th{background:#1b2b40;cursor:pointer;white-space:nowrap}tbody tr:hover{background:#1b2b40}.scroll{overflow:auto;max-height:680px}input{padding:12px;margin:10px 0;width:min(90%,500px);background:#17263a;color:white;border:1px solid #50627b;border-radius:6px}li{margin:8px 0}'
 js='const table=document.querySelector("#samples"),body=table.tBodies[0];document.querySelector("#filter").oninput=e=>{for(const row of body.rows)row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase());};for(const [i,head]of [...table.tHead.rows[0].cells].entries()){let asc=true;const sort=()=>{const rows=[...body.rows];rows.sort((a,b)=>{const x=a.cells[i].textContent,y=b.cells[i].textContent,n=Number(x),m=Number(y);return(asc?1:-1)*(Number.isFinite(n)&&Number.isFinite(m)?n-m:x.localeCompare(y));});rows.forEach(row=>body.append(row));asc=!asc;};head.onclick=sort;head.onkeydown=e=>{if(e.key==="Enter")sort();};}'
 (root/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Advanced story audit</title><style>'+css+'</style>'+''.join(body)+'<script>'+js+'</script></html>');print('Dashboard:',root/'index.html')
if __name__=='__main__':main()
